import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { sendShopifyUninstallEmail } from "../_shared/shopify-uninstall-email.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers":
    "Content-Type, Authorization, X-Client-Info, Apikey, X-Shopify-Welcome-Email-Secret",
};

type UninstallEmailBody = {
  shop_domain?: string;
  shop_name?: string;
  shop_email?: string;
  country_code?: string;
  force?: boolean;
};

function jsonResponse(body: Record<string, unknown>, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const welcomeSecret = Deno.env.get("SHOPIFY_WELCOME_EMAIL_SECRET")?.trim();
  if (welcomeSecret) {
    const headerSecret = req.headers.get("X-Shopify-Welcome-Email-Secret")?.trim();
    if (headerSecret !== welcomeSecret) {
      return jsonResponse({ error: "Invalid X-Shopify-Welcome-Email-Secret" }, 401);
    }
  }

  let body: UninstallEmailBody;
  try {
    body = (await req.json()) as UninstallEmailBody;
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  const shopDomain = body.shop_domain?.trim().toLowerCase();
  const shopName = body.shop_name?.trim();
  const shopEmail = body.shop_email?.trim().toLowerCase();

  if (!shopDomain || !shopName || !shopEmail) {
    return jsonResponse({
      error: "shop_domain, shop_name, and shop_email are required",
    }, 400);
  }

  try {
    const result = await sendShopifyUninstallEmail({
      shopDomain,
      shopName,
      shopEmail,
      countryCode: body.country_code,
      force: body.force,
    });

    return jsonResponse(result);
  } catch (error) {
    console.error("[shopify-uninstall-email] send failed:", error);
    return jsonResponse({
      error: error instanceof Error ? error.message : "Failed to send uninstall email",
    }, 500);
  }
});

import { createClient, SupabaseClient } from "jsr:@supabase/supabase-js@2";
import { localeFromCountryCode } from "./locale-from-country.ts";
import { buildUninstallFeedbackEmail } from "./shopify-uninstall-templates.ts";
import { sendZohoEmail } from "./zoho-mail.ts";

export type UninstallEmailInput = {
  shopDomain: string;
  shopName: string;
  shopEmail: string;
  countryCode?: string | null;
  force?: boolean;
};

export type UninstallEmailResult = {
  ok: boolean;
  skipped: boolean;
  reason?: string;
  locale?: string;
  message_id?: string;
  sent_at?: string;
};

function getSupabase(): SupabaseClient {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );
}

export async function resolveShopContact(
  shopDomain: string,
  payload: {
    shopName?: string;
    shopEmail?: string;
    countryCode?: string | null;
  },
): Promise<{ shopName: string; shopEmail: string; countryCode: string | null } | null> {
  const normalizedDomain = shopDomain.trim().toLowerCase();
  let shopName = payload.shopName?.trim() || "";
  let shopEmail = payload.shopEmail?.trim().toLowerCase() || "";
  let countryCode = payload.countryCode?.trim().toUpperCase() ?? null;

  const supabase = getSupabase();

  if (!shopEmail || !countryCode) {
    const { data: welcome } = await supabase
      .from("shopify_welcome_emails")
      .select("shop_contact_email, shop_country_code")
      .eq("shop_domain", normalizedDomain)
      .maybeSingle();

    if (!shopEmail && welcome?.shop_contact_email) {
      shopEmail = welcome.shop_contact_email.trim().toLowerCase();
    }
    if (!countryCode && welcome?.shop_country_code) {
      countryCode = welcome.shop_country_code;
    }
  }

  if (!shopEmail || !countryCode) {
    const { data: shop } = await supabase
      .from("shopify_shops")
      .select("shop_contact_email, shop_country_code")
      .eq("shop_domain", normalizedDomain)
      .maybeSingle();

    if (!shopEmail && shop?.shop_contact_email) {
      shopEmail = shop.shop_contact_email.trim().toLowerCase();
    }
    if (!countryCode && shop?.shop_country_code) {
      countryCode = shop.shop_country_code;
    }
  }

  if (!shopEmail) {
    return null;
  }

  return {
    shopName: shopName || normalizedDomain,
    shopEmail,
    countryCode,
  };
}

export async function sendShopifyUninstallEmail(
  input: UninstallEmailInput,
): Promise<UninstallEmailResult> {
  const shopDomain = input.shopDomain.trim().toLowerCase();
  const shopName = input.shopName.trim();
  const shopEmail = input.shopEmail.trim().toLowerCase();

  if (!shopDomain || !shopName || !shopEmail) {
    throw new Error("shopDomain, shopName, and shopEmail are required");
  }

  const supabase = getSupabase();

  const { data: existingSend, error: lookupError } = await supabase
    .from("shopify_uninstall_emails")
    .select("sent_at")
    .eq("shop_domain", shopDomain)
    .maybeSingle();

  if (lookupError) {
    throw new Error("Failed to lookup uninstall email record");
  }

  if (existingSend?.sent_at && !input.force) {
    return {
      ok: true,
      skipped: true,
      reason: "already_sent",
      sent_at: existingSend.sent_at,
    };
  }

  const locale = localeFromCountryCode(input.countryCode);
  const emailContent = buildUninstallFeedbackEmail(locale, shopName);

  const messageId = await sendZohoEmail({
    toAddress: shopEmail,
    subject: emailContent.subject,
    htmlContent: emailContent.html,
    textContent: emailContent.text,
  });

  const sentAt = new Date().toISOString();

  const { error: insertError } = await supabase
    .from("shopify_uninstall_emails")
    .upsert(
      {
        shop_domain: shopDomain,
        shop_contact_email: shopEmail,
        shop_country_code: input.countryCode?.trim().toUpperCase() ?? null,
        locale,
        zoho_message_id: messageId,
        sent_at: sentAt,
      },
      { onConflict: "shop_domain" },
    );

  if (insertError) {
    console.error("[shopify-uninstall-email] tracking insert failed:", insertError);
  }

  await supabase
    .from("shopify_welcome_emails")
    .delete()
    .eq("shop_domain", shopDomain);

  await supabase
    .from("shopify_shops")
    .update({
      shop_contact_email: shopEmail,
      shop_country_code: input.countryCode?.trim().toUpperCase() ?? null,
      welcome_email_sent_at: null,
      billing_status: "cancelled",
      updated_at: sentAt,
    })
    .eq("shop_domain", shopDomain);

  return {
    ok: true,
    skipped: false,
    locale,
    message_id: messageId,
    sent_at: sentAt,
  };
}

import type { WelcomeLocale } from "./locale-from-country.ts";

export type UninstallEmailContent = {
  subject: string;
  html: string;
  text: string;
};

const SUPPORT_EMAIL = "contato@omafit.co";

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export function buildUninstallFeedbackEmail(
  locale: WelcomeLocale,
  shopName: string,
): UninstallEmailContent {
  const copy = {
    pt: {
      subject: "Sentimos sua saída — podemos conversar?",
      greeting: `Olá, equipe da ${shopName},`,
      intro:
        "Notamos que você desinstalou o Omafit da sua loja Shopify. Queríamos saber se está tudo bem.",
      ask:
        "Poderia nos contar o motivo? Foi algo na implementação, no produto, no preço ou no suporte? Sua resposta nos ajuda a melhorar.",
      offer:
        "Se quiser, responda este e-mail — adoraríamos conversar e ver juntos se há algo que possamos resolver.",
      signOff: "Obrigado pelo tempo com o Omafit,\nEquipe Omafit",
    },
    es: {
      subject: "Lamentamos tu partida — ¿podemos hablar?",
      greeting: `Hola, equipo de ${shopName},`,
      intro:
        "Notamos que desinstalaste Omafit de tu tienda Shopify. Queríamos saber cómo estás.",
      ask:
        "¿Podrías contarnos el motivo? ¿Fue la implementación, el producto, el precio o el soporte? Tu feedback nos ayuda a mejorar.",
      offer:
        "Si quieres, responde a este correo — nos encantaría conversar y ver si podemos resolver la situación juntos.",
      signOff: "Gracias por haber probado Omafit,\nEquipo Omafit",
    },
    en: {
      subject: "Sorry to see you go — can we talk?",
      greeting: `Hi ${shopName} team,`,
      intro:
        "We noticed you uninstalled Omafit from your Shopify store. We wanted to check in.",
      ask:
        "Would you mind sharing why? Was it setup, the product, pricing, or support? Your feedback helps us improve.",
      offer:
        "If you'd like, reply to this email — we'd love to talk and see if there's anything we can help resolve.",
      signOff: "Thanks for trying Omafit,\nThe Omafit team",
    },
  }[locale];

  const text = [
    copy.greeting,
    "",
    copy.intro,
    "",
    copy.ask,
    "",
    copy.offer,
    "",
    copy.signOff,
    SUPPORT_EMAIL,
  ].join("\n");

  const html = `<!DOCTYPE html>
<html lang="${locale}">
  <body style="font-family: Inter, Arial, sans-serif; line-height: 1.6; color: #1f2937; max-width: 560px; margin: 0 auto; padding: 24px;">
    <p style="font-size: 18px; font-weight: 600;">${escapeHtml(copy.greeting)}</p>
    <p>${escapeHtml(copy.intro)}</p>
    <p>${escapeHtml(copy.ask)}</p>
    <p>${escapeHtml(copy.offer)}</p>
    <p style="white-space: pre-line; color: #4b5563;">${escapeHtml(copy.signOff)}</p>
    <p style="color: #6b7280; font-size: 14px;">${SUPPORT_EMAIL}</p>
  </body>
</html>`;

  return { subject: copy.subject, html, text };
}

type ZohoTokenResponse = {
  access_token?: string;
  error?: string;
};

type ZohoSendResponse = {
  status?: { code?: number; description?: string };
  data?: { messageId?: string };
};

let cachedAccessToken: { token: string; expiresAt: number } | null = null;

function accountsBaseUrl(): string {
  return (Deno.env.get("ZOHO_ACCOUNTS_URL") ?? "https://accounts.zoho.com").replace(/\/$/, "");
}

function mailApiBaseUrl(): string {
  return (Deno.env.get("ZOHO_MAIL_API_URL") ?? "https://mail.zoho.com").replace(/\/$/, "");
}

async function refreshAccessToken(): Promise<string> {
  const clientId = Deno.env.get("ZOHO_CLIENT_ID")?.trim();
  const clientSecret = Deno.env.get("ZOHO_CLIENT_SECRET")?.trim();
  const refreshToken = Deno.env.get("ZOHO_REFRESH_TOKEN")?.trim();

  if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Missing ZOHO_CLIENT_ID, ZOHO_CLIENT_SECRET, or ZOHO_REFRESH_TOKEN");
  }

  const params = new URLSearchParams({
    refresh_token: refreshToken,
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: "refresh_token",
  });

  const response = await fetch(`${accountsBaseUrl()}/oauth/v2/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  });

  const payload = (await response.json()) as ZohoTokenResponse;
  if (!response.ok || !payload.access_token) {
    throw new Error(payload.error ?? `Zoho token refresh failed (${response.status})`);
  }

  cachedAccessToken = {
    token: payload.access_token,
    expiresAt: Date.now() + 50 * 60 * 1000,
  };

  return payload.access_token;
}

async function getAccessToken(): Promise<string> {
  if (cachedAccessToken && cachedAccessToken.expiresAt > Date.now()) {
    return cachedAccessToken.token;
  }
  return refreshAccessToken();
}

export type SendZohoEmailInput = {
  toAddress: string;
  subject: string;
  htmlContent: string;
  textContent: string;
  fromAddress?: string;
};

export async function sendZohoEmail(input: SendZohoEmailInput): Promise<string> {
  const accountId = Deno.env.get("ZOHO_ACCOUNT_ID")?.trim();
  const fromAddress = (input.fromAddress ?? Deno.env.get("ZOHO_FROM_ADDRESS") ?? "contato@omafit.co").trim();

  if (!accountId) {
    throw new Error("Missing ZOHO_ACCOUNT_ID");
  }

  const accessToken = await getAccessToken();
  const response = await fetch(`${mailApiBaseUrl()}/api/accounts/${accountId}/messages`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      Authorization: `Zoho-oauthtoken ${accessToken}`,
    },
    body: JSON.stringify({
      fromAddress,
      toAddress: input.toAddress,
      subject: input.subject,
      content: input.htmlContent,
      mailFormat: "html",
      askReceipt: "no",
    }),
  });

  const payload = (await response.json()) as ZohoSendResponse;
  if (!response.ok || payload.status?.code !== 200) {
    throw new Error(
      payload.status?.description ?? `Zoho Mail send failed (${response.status})`,
    );
  }

  return payload.data?.messageId ?? "sent";
}

export type WelcomeLocale = "pt" | "es" | "en";

const PORTUGUESE_COUNTRIES = new Set([
  "BR", "PT", "AO", "MZ", "CV", "GW", "ST", "TL",
]);

const SPANISH_COUNTRIES = new Set([
  "ES", "MX", "AR", "CO", "CL", "PE", "VE", "EC", "GT", "CU", "BO", "DO",
  "HN", "PY", "SV", "NI", "CR", "PA", "UY", "PR", "GQ",
]);

export function localeFromCountryCode(
  countryCode: string | null | undefined,
): WelcomeLocale {
  const code = (countryCode ?? "").trim().toUpperCase();
  if (!code) return "en";
  if (PORTUGUESE_COUNTRIES.has(code)) return "pt";
  if (SPANISH_COUNTRIES.has(code)) return "es";
  return "en";
}
